// Emit src/assets/images.ts and submodules under src/assets/images/ — Metro
// needs static require() calls, so these files are regenerated whenever the asset
// manifest changes.
import fs from "node:fs";
import path from "node:path";
import url from "node:url";

const defaultRoot = path.dirname(
  path.dirname(url.fileURLToPath(import.meta.url)),
);

function generateIconsTs(manifest, root) {
  const exists = (rel) => fs.existsSync(path.join(root, "assets/game", rel));
  const lines = [
    "// GENERATED by tools/gen_images_ts.mjs — do not edit by hand.",
    "",
    "export const SPOTIT_ICONS: Record<string, number> = {",
  ];
  for (const name of manifest.spotit.icons) {
    lines.push(
      `  ${name}: require('../../../assets/game/spotit/${name}.png'),`,
    );
  }
  lines.push(
    "};",
    "",
    "// precomputed silhouettes (rn-web tintColor masks stretch/crop sprites)",
  );
  lines.push("export const SPOTIT_SHADOWS: Record<string, number> = {");
  for (const name of manifest.spotit.icons) {
    if (exists(`spotit/${name}_shadow.png`)) {
      lines.push(
        `  ${name}: require('../../../assets/game/spotit/${name}_shadow.png'),`,
      );
    }
  }
  lines.push(
    "};",
    "",
    "export const DRESSUP_ICONS: Record<string, number> = {",
  );
  for (const name of manifest.dressup ?? []) {
    if (exists(`dressup/${name}.png`)) {
      lines.push(
        `  ${name}: require('../../../assets/game/dressup/${name}.png'),`,
      );
    }
  }
  lines.push(
    "};",
    "",
    "export const CHARACTER_ICONS: Record<string, number> = {",
  );
  for (const name of manifest.characters ?? []) {
    if (exists(`characters/${name}.png`)) {
      lines.push(
        `  ${name}: require('../../../assets/game/characters/${name}.png'),`,
      );
    }
  }
  lines.push("};", "", "export const ANIMAL_ICONS: Record<string, number> = {");
  for (const [animal, poses] of Object.entries(manifest.animalPoses ?? {})) {
    for (const pose of poses) {
      if (exists(`animals/${animal}_${pose}.png`)) {
        lines.push(
          `  ${animal}_${pose}: require('../../../assets/game/animals/${animal}_${pose}.png'),`,
        );
      }
    }
  }
  lines.push("};", "", "export const UI_IMAGES = {");
  for (const f of fs.readdirSync(path.join(root, "assets/game/ui")).sort()) {
    const key = f.replace(/\.(png|jpg)$/, "");
    lines.push(`  ${key}: require('../../../assets/game/ui/${f}'),`);
  }
  lines.push("} as const;", "");
  return lines.join("\n");
}

function generateRhymeTs(root) {
  const lines = [
    "// GENERATED by tools/gen_images_ts.mjs — do not edit by hand.",
    "",
    "export const RHYME_SPRITES: Record<string, number> = {",
  ];
  const rhymeDir = path.join(root, "assets/game/rhyme");
  for (const f of fs.existsSync(rhymeDir)
    ? fs.readdirSync(rhymeDir).sort()
    : []) {
    const key = f.replace(/\.(png|jpg)$/, "");
    lines.push(`  ${key}: require('../../../assets/game/rhyme/${f}'),`);
  }
  lines.push("};", "");
  return lines.join("\n");
}

function generateImagesTs(manifest, root) {
  const exists = (rel) => fs.existsSync(path.join(root, "assets/game", rel));
  const lines = [
    "// GENERATED by tools/gen_images_ts.mjs — do not edit by hand.",
    "/* eslint-disable @typescript-eslint/no-require-imports */",
    "",
    "export * from './images/icons';",
    "export * from './images/rhyme';",
    "",
    "export const SCENE_IMAGES: Record<string, number> = {",
  ];
  const sceneFiles = new Set();
  for (const d of manifest.diff) {
    if (d.pool) {
      sceneFiles.add(d.image);
      for (const e of d.pool) sceneFiles.add(e.patch);
    } else {
      sceneFiles.add(d.imageA);
      sceneFiles.add(d.imageB);
    }
  }
  for (const h of manifest.hidden) {
    sceneFiles.add(h.image);
    for (const t of h.targets) {
      sceneFiles.add(t.thumb);
      const shadow = t.thumb.replace(/\.png$/, "_shadow.png");
      if (exists(shadow)) sceneFiles.add(shadow);
    }
  }
  for (const st of manifest.stories ?? []) {
    for (const n of Object.values(st.nodes)) {
      sceneFiles.add(n.image);
      if (n.scare) sceneFiles.add(n.scare.pop);
      for (const c of n.choices ?? []) if (c.icon) sceneFiles.add(c.icon);
    }
  }
  for (const r of manifest.escape ?? []) {
    sceneFiles.add(r.image);
    for (const h of r.hotspots) {
      if (h.pop) sceneFiles.add(h.pop);
      if (h.afterScene) sceneFiles.add(h.afterScene);
      if (h.revealScene) sceneFiles.add(h.revealScene);
      if (h.takenScene) sceneFiles.add(h.takenScene);
    }
  }
  for (const f of [...sceneFiles].sort()) {
    lines.push(`  '${f}': require('../../assets/game/${f}'),`);
  }
  lines.push(
    "};",
    "",
    "// small jpg derivatives for picker cards (fall back to full image)",
  );
  lines.push("export const SCENE_THUMBS: Record<string, number> = {");
  // Every picture a ScenePicker card can show. Keep this in step with what
  // gen_thumbs.py renders: a scene that has a thumb on disk but no entry here
  // silently falls back to the full-size image in the picker, which is how
  // the story picker came to load 43.7 MB of 1280x720 PNGs to draw 48 cards.
  const thumbable = new Set();
  for (const d of manifest.diff) thumbable.add(d.image ?? d.imageA);
  for (const h of manifest.hidden) thumbable.add(h.image);
  for (const r of manifest.escape ?? []) thumbable.add(r.image);
  for (const st of manifest.stories ?? []) thumbable.add(st.nodes.start.image);
  for (const f of [...thumbable].sort()) {
    const t = f.replace(/\.(png|jpg)$/, "_thumb.jpg");
    if (exists(t)) lines.push(`  '${f}': require('../../assets/game/${t}'),`);
  }
  lines.push("};", "");

  // Music Box scene assets (panoramic strips, vehicle/picker sprites, object sprites)
  const mbDir = path.join(root, "assets/game/musicbox");
  if (fs.existsSync(mbDir)) {
    lines.push("export const MUSICBOX_IMAGES: Record<string, number> = {");
    for (const scene of fs.readdirSync(mbDir).sort()) {
      const sd = path.join(mbDir, scene);
      if (!fs.statSync(sd).isDirectory()) continue;
      for (const f of fs.readdirSync(sd).sort()) {
        if (!f.endsWith(".png")) continue;
        const key = `${scene}/${f.replace(".png", "")}`;
        lines.push(
          `  '${key}': require('../../assets/game/musicbox/${scene}/${f}'),`,
        );
      }
    }
    lines.push("};", "");
  }

  return lines.join("\n");
}

export function generateImages({
  root = defaultRoot,
  outDir = path.join(root, "src/assets"),
} = {}) {
  const manifest = JSON.parse(
    fs.readFileSync(path.join(root, "src/assets/manifest.json"), "utf8"),
  );
  const imagesDir = path.join(outDir, "images");

  if (!fs.existsSync(outDir)) {
    fs.mkdirSync(outDir, { recursive: true });
  }
  if (!fs.existsSync(imagesDir)) {
    fs.mkdirSync(imagesDir, { recursive: true });
  }

  const iconsTs = generateIconsTs(manifest, root);
  const rhymeTs = generateRhymeTs(root);
  const imagesTs = generateImagesTs(manifest, root);

  fs.writeFileSync(path.join(imagesDir, "icons.ts"), iconsTs);
  fs.writeFileSync(path.join(imagesDir, "rhyme.ts"), rhymeTs);
  fs.writeFileSync(path.join(outDir, "images.ts"), imagesTs);

  return {
    "images/icons.ts": iconsTs,
    "images/rhyme.ts": rhymeTs,
    "images.ts": imagesTs,
  };
}

const isMain =
  process.argv[1] &&
  url.fileURLToPath(import.meta.url) === path.resolve(process.argv[1]);
if (isMain) {
  const customOut = process.argv[2] ? path.resolve(process.argv[2]) : undefined;
  generateImages(customOut ? { outDir: customOut } : undefined);
  console.log("wrote src/assets/images.ts");
}
